import React from "react";
import clsx from "clsx";
import { createUseStyles } from "../../lib/styling";
import { spacingToTokenValue } from "../../lib/utils";
import { FlexLayout, FlexLayoutProps } from "../internal/FlexLayout";
import {
  AlignItems,
  JustifyContent,
  JustifyContentValues,
  Spacing,
  SpacingValues,
} from "../helperTypes";

export type InlineProps = {
  /** Aligns children horizontally */
  align?: JustifyContent;
  /** Aligns children vertically */
  alignY?: AlignItems;
  /** Specifies the gap beween children */
  spacing?: Spacing;
  /** If true, children will wrap on multiple lines */
  wrap?: boolean;
} & FlexLayoutProps;

const useStyles = createUseStyles(() => {
  const alignItemsClasses: any = {};
  JustifyContentValues.forEach((align) => {
    alignItemsClasses[`align-${align}`] = {
      alignItems:
        align !== "start" && align !== "end" ? align : `flex-${align}`,
    };
  });

  const justifyContentClasses: any = {};
  JustifyContentValues.forEach((align) => {
    justifyContentClasses[`justify-${align}`] = {
      justifyContent:
        align !== "start" && align !== "end" ? align : `flex-${align}`,
    };
  });

  const spacingClasses: any = {};
  SpacingValues.forEach((spacing) => {
    spacingClasses[`spacing-${spacing}`] = {
      margin: `calc(-${spacingToTokenValue(spacing)} / 2)`,
    };
    spacingClasses[`child--spacing-${spacing}`] = {
      margin: `calc(${spacingToTokenValue(spacing)} / 2)`,
    };
  });

  return {
    root: {
      display: "flex",
      flexWrap: "nowrap",
    },
    wrap: {
      flexWrap: "wrap",
    },
    ...alignItemsClasses,
    ...justifyContentClasses,
    ...spacingClasses,
  };
}, "inline");

const Inline = (props: InlineProps) => {
  const {
    className,
    childrenClassName,
    align = "start",
    alignY = "center",
    spacing,
    wrap,
    ...rest
  } = props;
  const classes = useStyles({ spacing, align });
  return (
    <FlexLayout
      className={clsx(
        className,
        classes.root,
        wrap && classes.wrap,
        classes[`justify-${align}`],
        classes[`align-${alignY}`],
        spacing && classes[`spacing-${spacing}`]
      )}
      childrenClassName={clsx(
        classes.child,
        spacing && classes[`child--spacing-${spacing}`],
        childrenClassName
      )}
      {...rest}
    />
  );
};

export default Inline;
